import type { MetadataRoute } from 'next'

const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL ?? 'https://www.atriumad.com'

export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: '*',
      allow: '/',
    },
    // The second sitemap lists Insights articles; it is generated by /api/insights.php.
    sitemap: [`${SITE_URL}/sitemap.xml`, `${SITE_URL}/insights/sitemap.xml`],
  }
}

export const dynamic = "force-static"
